figures.script:
var bat = create("battery", { V: 6, name: "bat" });
var lamp = create("bulb", { R: 12, name: "lamp" });
var sw = create("switch", { closed: 1, name: "sw" });
var am = create("ammeter", { name: "am" });
connect(bat.positive, sw.a, "wire");
connect(sw.b, lamp.a, "wire");
connect(lamp.b, am.a, "wire");
connect(am.b, bat.negative, "wire");

